/* Versioned account shell. No old practitioner seed or direct reset writer. */
(function(w){'use strict';const E=w.NutriRegistrationEntry;if(!E||E.buildId!=='registration-entry-v3-c1')throw Error('REGISTRATION_ENTRY_REQUIRED');
function mount(){const d=w.document,page=d.body.dataset.originalPage,management=page==='profile-management';if(!['profile','profile-management','settings'].includes(page))throw Error('SHELL_PAGE_MISMATCH');const anchor=d.getElementById('original-page');if(!anchor)throw Error('SHELL_ROOT_REQUIRED');const S=E.store;let active=true,shown=null,reset=null,restore=null,unsubscribe=null,unentry=null,initializing=false,initSerial=0,resetDialog=null,resetContext=null,resetLaunch=null,resetConfirm=null,storageNote=null,undoNote=null,initialHashHandled=false;
const section=d.createElement('section');section.className='registration-v3-shell ag-shell';section.setAttribute('aria-label','沈先生合成账号与服务设置');const node=(tag,text)=>{const n=d.createElement(tag);n.textContent=text;return n;};if(management){
 section.classList.add('np-profile');const hero=node('header','');hero.className='np-account';const avatar=node('span','沈');avatar.className='np-avatar';avatar.setAttribute('aria-hidden','true');const identity=node('div','');identity.append(node('p','我的营养生活'),node('h2','沈先生'),node('span','合成演示账号'));hero.append(avatar,identity);section.append(hero);const notice=node('p','仅本地合成体验 · AI 未连接。请勿填写真实健康、身份或地址资料。');notice.className='np-notice';section.append(notice);
}else if(page==='settings'){const title=node('h1','数据与隐私');title.className='ag-page-title';section.append(title);}else section.append(node('h2','沈先生 · 隔离合成账号'));
const links=d.createElement('nav');links.setAttribute('aria-label','合成账号服务');
const groups=[['订单与购物',[['shop.html','演示商城','发现演示商品','购'],['orders.html','我的订单','查看付款与退款演示','单'],['address.html','演示地址','仅保存虚构地址','址']]],['邀请与权益',[['wallet.html','邀请与优惠','邀请关系、优惠规则与模拟账本','惠']]],['健康与饮食',[['aiAgent.html','营养助手','问询与饮食陪伴','聊'],['diet.html','饮食记录','记录一日三餐','食'],['intake.html','营养摄入','查看摄入与目标','养'],['health-calendar.html','健康记录','身体、家庭与慢病记录','记']]],['营养师与服务',[['student.html','营养师登记与服务','本地登记演示，不代表真实认证','师'],['commerce-admin.html','商品审核演示','本地商品上架与审核流程','审'],['settings.html','设置','演示说明与账号重置','设']]]];
function link(href,label,sub,icon){const a=node('a',management?'':label);a.href=href;a.addEventListener('click',e=>{if(!E.confirmLeave(false))e.preventDefault();});if(management){const symbol=node('span',icon);symbol.className='np-entry-icon';symbol.setAttribute('aria-hidden','true');const text=node('span','');text.className='np-entry-text';text.append(node('strong',label),node('small',sub));const arrow=node('span','›');arrow.className='np-chevron';arrow.setAttribute('aria-hidden','true');a.append(symbol,text,arrow);}return a;}
if(management){links.className='np-groups';for(const [title,entries]of groups){const group=node('section','');group.className='np-group';group.append(node('h3',title));const items=node('div','');items.className='np-entries';for(const entry of entries)items.append(link(...entry));group.append(items);links.append(group);}}
else if(page==='profile')for(const [href,label]of [['aiAgent.html','营养助手'],['diet.html','饮食记录'],['intake.html','营养摄入'],['shop.html','演示商城'],['profile.html','我的首页'],['wallet.html','邀请与优惠'],['orders.html','我的订单'],['address.html','演示地址'],['student.html','营养师登记与服务'],['commerce-admin.html','商品审核演示'],['health-calendar.html','健康记录'],['aiAgent.html','营养助手'],['settings.html','设置']])links.append(link(href,label));if(page!=='settings')section.append(links);
const summary=node('p','正在等待完整版本与合成账号采用…'),branch=node('p',''),limits=node('p','旧 v2 与 v3 是各自保留的分支，不会自动合并。整账号重置的撤销只保留在当前页面；刷新后不能凭空恢复。本界面尚不提供持久备份浏览或任意坏档修复。'),feedback=node('p','');feedback.setAttribute('role','status');feedback.setAttribute('aria-live','polite');if(management){summary.className='np-summary';const details=node('details','');details.className='np-data-details';details.append(node('summary','本地演示数据与恢复说明'),branch,limits);section.append(summary,details);}else if(page!=='settings')section.append(summary,branch,limits);
if(page==='settings'){
 function card(title,icon,tone){const box=node('section','');box.className='ag-glass ag-card';const head=node('header',''),mark=node('span',icon);mark.className='ag-icon '+tone;mark.setAttribute('aria-hidden','true');head.append(mark,node('h2',title));box.append(head);section.append(box);return box;}
 const storage=card('数据存储','▤','ag-blue');storageNote=node('p','正在核对当前存储方式…');storage.append(storageNote,node('p','本页管理沈先生合成账号，不读取独立个人本机区。当前页面不会上传数据或连接外部服务。'));
 const tags=node('div','');tags.className='ag-tags';for(const label of ['合成饮食记录','合成指标','目标与设置','订单与优惠','合成家庭','营养师登记'])tags.append(node('span',label));storage.append(tags);
 const backup=card('数据备份与恢复','↗','ag-blue');backup.append(node('p','本页尚未提供整账号文件导出或导入；请勿把界面入口理解为已有持久备份。'));
 const exportButton=node('button','整账号导出 / 导入 · 尚未提供');exportButton.type='button';exportButton.disabled=true;backup.append(exportButton);
 restore=node('button','撤销本页上次重置');restore.type='button';restore.disabled=true;restore.dataset.accountAction='undo';undoNote=node('p','尚无可撤销的本页重置。刷新、离开或重置后再修改资料，都会使本页撤销不可用。');undoNote.className='ag-help';backup.append(restore,undoNote);
 restore.addEventListener('click',()=>{if(!active||!shown||!equal(shown,S.context())||E.hasPending()||!E.canUndo())return;void E.restoreAccount({guard:()=>active,onSuccess:accountSuccess,onError:accountError});});
 const services=card('服务状态','♧','ag-green');services.append(node('p','当前均未连接；没有云同步、真实支付或账号身份认证。'));const list=node('ul','');list.className='ag-service-list';for(const label of ['智能对话（LLM）','支付服务','身份认证']){const item=node('li','');item.append(node('span',label),node('strong','未连接'));list.append(item);}services.append(list);
 const recovery=card('本机状态与恢复说明','ⓘ','ag-neutral');summary.className='ag-summary';branch.className='ag-help';limits.className='ag-help';recovery.append(summary,branch,limits);
 const danger=card('重置合成账号','↻','ag-red');danger.append(node('p','将健康、商城、家庭及营养师状态恢复为初始合成示例。仅独立的个人本机区不受此操作影响。'));reset=node('button','查看重置范围');reset.type='button';reset.disabled=true;reset.className='ag-danger-outline';reset.dataset.accountAction='reset-open';danger.append(reset);
 resetDialog=node('dialog','');resetDialog.className='ag-reset-dialog';resetDialog.setAttribute('aria-labelledby','account-reset-title');resetDialog.setAttribute('aria-describedby','account-reset-scope');resetDialog.innerHTML='<div class="ag-dialog-inner"><span class="ag-reset-symbol" aria-hidden="true">↻</span><h2 id="account-reset-title">确认重置整个合成账号？</h2><p>这将恢复沈先生合成账号下的健康、商城、家庭和营养师初始示例；旧角色、表单与同意将失效。</p><p class="ag-reset-scope" id="account-reset-scope">仅独立的个人本机区不受影响；合成账号中的记录并不保留。</p><div class="ag-dialog-note"><h3>恢复边界</h3><ul><li>旧 v2 分支保留，不会自动合并。</li><li>撤销只在本页、当前状态仍匹配时可用；刷新或后续修改后不可依赖此撤销。</li><li>本页没有整账号文件导出 / 导入或任意坏档修复。</li></ul></div><p class="ag-help">继续后仍需通过现有系统确认，才会执行重置。</p><p class="ag-reset-stale" data-reset-stale role="status" aria-live="polite"></p><div class="ag-dialog-actions"><button type="button" data-reset-cancel>取消</button><button type="button" class="ag-destructive" data-reset-confirm>确认重置</button></div></div>';
 section.append(resetDialog);resetConfirm=resetDialog.querySelector('[data-reset-confirm]');
 function closeReset(){resetContext=null;if(resetDialog.open)resetDialog.close();resetLaunch?.focus();}
 function openReset(){if(!active||!shown||!equal(shown,S.context())||E.hasPending()||reset.disabled)return;if(typeof resetDialog.showModal!=='function'){feedback.textContent='当前浏览器不支持安全确认对话框，未执行重置。请使用支持 dialog 的浏览器。';return;}resetContext=Object.freeze({...shown});resetLaunch=reset;resetConfirm.disabled=false;resetDialog.querySelector('[data-reset-stale]').textContent='';resetDialog.showModal();resetDialog.querySelector('[data-reset-cancel]').focus();}
 reset.addEventListener('click',openReset);
 resetDialog.querySelector('[data-reset-cancel]').addEventListener('click',closeReset);
 resetDialog.addEventListener('cancel',event=>{event.preventDefault();closeReset();});
 resetConfirm.addEventListener('click',()=>{if(!resetDialog.open)return;const context=resetContext;if(!active||!context||!equal(context,shown)||!equal(context,S.context())||E.hasPending()){closeReset();feedback.textContent='记录已变化，重置未执行。请核对后重新打开确认。';return;}closeReset();void E.resetAccount({context,guard:()=>active,onSuccess:accountSuccess,onError:accountError});});
}
const reread=node('button','重新读取当前合成记录');reread.type='button';reread.className='np-refresh ag-refresh';feedback.className='np-feedback ag-feedback';reread.disabled=true;reread.addEventListener('click',()=>{if(active&&!initializing&&!E.hasPending())void initialize();});section.append(reread,feedback);if(page==='profile')anchor.before(section);else anchor.append(section);if(management)anchor.querySelector('[data-management-loading]')?.remove();if(page==='profile')section.hidden=true;if(management){const back=node('a','‹ 返回我的');back.href='profile.html';back.className='np-management-back';back.addEventListener('click',e=>{if(!E.confirmLeave(false))e.preventDefault();});section.prepend(back);}
function renderOriginalProfile(s){
 const template=d.getElementById('original-template');if(!template)throw Error('ORIGINAL_PROFILE_TEMPLATE_REQUIRED');
 const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const members=s.health.family?.members;const values={name:s.profile.name,orders:s.commerce.orders.length,family:Array.isArray(members)?members.filter(m=>m.active).length+' 位合成成员':'尚未启用'};
 anchor.innerHTML=template.innerHTML.replace(/{{([\s\S]*?)}}/g,(_,key)=>escape(values[key.trim()]??''));
}

function profileNavigate(e){const target=e.target.closest?.('[data-profile-href],.profile-management-entry');if(!target)return;if(e.type==='keydown'&&!['Enter',' '].includes(e.key))return;e.preventDefault();if(!active||!shown||!equal(shown,S.context())||!E.confirmLeave(false))return;w.location.href=target.dataset.profileHref||target.getAttribute('href');}if(page==='profile'){anchor.addEventListener('click',profileNavigate);anchor.addEventListener('keydown',profileNavigate);}
const fields=['mode','accountId','protocolVersion','epoch','generation','revision'];function context(s){return Object.fromEntries(fields.map(k=>[k,s.meta[k]]));}function equal(a,b){return !!a&&!!b&&fields.every(k=>a[k]===b[k]);}
function controls(){if(!active)return;if(storageNote)storageNote.textContent=initializing||!shown?'正在核对当前存储方式；未核对前不能据此确认持久保存。':S.status().persistent?'已核验保存在此浏览器的合成分支；不是云端备份。':'当前仅本页内存；刷新或离开即丢失，不是持久保存。';if(undoNote)undoNote.textContent=E.canUndo()?'本页重置快照仍与当前状态匹配，可恢复整份合成账号。':'尚无可用的本页撤销；刷新、离开或后续修改后不能凭空恢复。';if(resetContext&&(!shown||!equal(resetContext,shown)||!equal(resetContext,S.context()))){resetConfirm.disabled=true;resetDialog.querySelector('[data-reset-stale]').textContent='记录已更新，本次确认已失效。请取消后核对当前记录，再重新打开。';}reread.disabled=initializing||E.hasPending()||E.view().phase!=='ready';if(reset)reset.disabled=initializing||!shown||E.hasPending()||!S.status().writable;if(restore)restore.disabled=initializing||!shown||!E.canUndo();}
function invalid(text){if(!active)return;shown=null;if(page==='profile')anchor.textContent='当前合成记录需要重新核对，请刷新后重新进入；现有记录没有改写。';summary.textContent='当前合成记录需要重新核对，不能据旧画面继续写入。';feedback.textContent=text;controls();}
function render(s){if(!active)return false;try{const c=context(s);if(!equal(c,S.context())){invalid('记录已变化，请重新读取；没有把新权限附在旧数据上。');return false;}shown=c;if(page==='profile')renderOriginalProfile(s);summary.textContent=`${s.profile.name} · ${s.health.demoDate} 演示日 · ${s.health.meals.length} 条餐食 / ${s.commerce.orders.length} 个演示订单 / ${s.practitioner.registration?.events?.length||0} 条登记操作记录`;branch.textContent=`当前 v${c.protocolVersion} · 代际 ${c.generation} / 版本 ${c.revision}；来源 ${s.meta.source.key}。${S.status().persistent?'仅此浏览器的合成分支。':'仅本页内存，导航或刷新即丢失。'}`;controls();return true;}catch(e){invalid(e.message);return false;}}
function refresh(){try{return render(S.read());}catch(e){invalid(e.message);return false;}}
function accountSuccess(r){if(!active)return;try{if(equal(context(r.state),S.context())){render(r.state);feedback.textContent=S.status().persistent?'整账号操作已核验保存；旧角色、表单和同意均已失效。':'整账号操作已完成，仅本页内存保留。';}else{refresh();feedback.textContent='整账号操作已写入，随后数据又有更新，请核对当前记录。';}}catch(e){invalid(e.message);}}
function accountError(e){if(!active)return;feedback.textContent=e.outcome==='unknown'?'操作结果尚未核对。请使用上方原请求重试，勿再次发起新重置。':e.outcome==='committed'?'写入已核验，当前界面需要重新读取。':e.message;controls();}
function destroy(){if(page==='profile'){anchor.removeEventListener('click',profileNavigate);anchor.removeEventListener('keydown',profileNavigate);}active=false;initSerial++;shown=null;resetContext=null;if(resetDialog?.open)resetDialog.close();reread.disabled=true;if(reset)reset.disabled=true;if(restore)restore.disabled=true;unsubscribe?.();unentry?.();}
w.addEventListener('pagehide',destroy);unentry=E.subscribe(controls);
async function initialize(){if(!active||initializing||E.hasPending())return false;const ticket=++initSerial,guard=()=>active&&ticket===initSerial;initializing=true;shown=null;controls();try{await S.initialize({guard});if(!guard())return false;if(!unsubscribe)unsubscribe=S.subscribe((next)=>{if(!active||initializing)return;if(next)render(next);else invalid('存档暂不可读，保留原数据，请点击重新读取当前合成记录。');});const ok=refresh();if(ok){feedback.textContent=S.status().notice;if(page==='settings'&&!initialHashHandled){initialHashHandled=true;if(w.location.hash==='#reset')queueMicrotask(()=>{if(active&&!initializing)reset.click();});}}return ok;}catch(e){if(guard())invalid(e.message+'；请点击重新读取当前合成记录。没有自动清空或重建。');return false;}finally{if(guard()){initializing=false;controls();}}}
const ready=initialize();return {ready,destroy};
}
E.register('account-shell',{buildId:'registration-web-v3-c1',mount});
})(window);
